INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(360700, 0, 3607, 0, 0, 9, 'Serpentshrine Cavern', 'Serpentshrine Cavern is the deepest hold of Coilfang Reservoir, a vast flooded cavern beneath Serpent Lake and the seat of Lady Vashj, matron of the Coilfang naga. Here the water drawn in from the bogs gathers, and the work never stops: Vashj''ir honor guards drive their workers at the pumps and valves, boasting that the reservoir fills nicely and that soon all of Draenor''s water will be theirs. Coilfang priestesses, shatterers, serpentguards and fathom-witches walk its halls, Greyheart Broken serve the naga as technicians, tidecallers and nether-mages, Tidewalker murlocs crowd one shore, and colossi of the bog and sporebats roam the wilder reaches. Frenzies swarm the dark water. Her lords hold the cavern''s outer chambers, and Vashj herself waits at its heart.', 'zones/serpentshrine_cavern.txt (map 548: area 3607 only); DB spawns map 548: Vashj''ir Honor Guard 21218, Greyheart Technician 21263, Tidecaller 21229, Nether-Mage 21230 (Broken models), Coilfang Priestess 21220, Shatterer 21301, Serpentguard 21298, Fathom-Witch 21299, Tidewalker Warrior 21225, Shaman 21226, Harpooner 21227, Hydromancer 21228, Depth-Seer 21224 (murloc models), Underbog Colossus 21251, Serpentshrine Sporebat 21246, Coilfang Frenzy Corpse 21689; bosses 21216, 21215, 21214, 21213, 21212; gameobject 184956 Strange Pool; creature_text 21218 groups 1-3 (patrol lines: Steady the pumps; Keep those pumps working; The reservoir fills nicely; Soon all of Draenor''s water will be ours; Direct the flow from the western bog; Lady Vashj expects our work to be done soon), run by the honor guards'' patrol scripts; creature_template 21212 Lady Vashj, subname Coilfang Matron; instance_serpent_shrine.cpp (Coilfang Frenzies summoned around swimmers until the Lurker Below falls)'),
(360701, 2, 3607, 1, 0, 9, 'Hydross the Unstable', 'Hydross the Unstable, called the Duke of Currents, is a great lord of water who dwells in a chamber of Serpentshrine Cavern. Tainted water spirits come to him one after another, and he purifies them and sends them on clean. Yet his name is earned. He tells intruders that he cannot allow them to interfere, and when he is drawn out of the cleansing field about him, the poison takes him at once: he cries out in pain and turns foul. Drawn back in, he grows clean, sighing that this is better, much better.', 'creature_template 21216 (subname Duke of Currents, type 4, display 20162 WaterElemental); fixed spawn 153018, map 548 only; boss_hydross_the_unstable.cpp (out of combat he summons Tainted Water Elementals that walk to him, are purified and leave as Purified Water Elementals; Cleansing Field aura; leaving it applies Corruption); creature_text 21216 groups 0 (I cannot allow you to interfere!), 1 (Better, much better.), 4 (Aaghh, the poison...)'),
(360702, 2, 3607, 2, 0, 9, 'The Lurker Below', 'At the center of Serpentshrine Cavern lies a strange pool, its water dark and still, and something lives beneath it that does not show itself to the idle. Only one who casts a line into the pool may draw it up: the Lurker Below, a great beast of the deep that surfaces in a rush of water. It spouts torrents across those who stand against it, lashes about in a whirling frenzy and bursts geysers beneath their feet, and when it dives again, Coilfang ambushers and guardians rise from the depths to fight in its place.', 'gameobject 184956 Strange Pool (map 548), go_strange_pool in boss_lurker_below.cpp (fishing it summons The Lurker Below 21217); creature_template 21217 (display 20216, Krakken model); boss_lurker_below.cpp (Spout, Whirl, Geyser, Water Bolt; on submerging summons Coilfang Ambushers 21865 and Coilfang Guardians 21873); creature_text 21217 group 0 (takes a deep breath)'),
(360703, 2, 3607, 3, 0, 9, 'Leotheras the Blind', 'Leotheras the Blind is a blood elf demon hunter, and he is a prisoner in Serpentshrine Cavern. Three Greyheart spellbinders keep him banished, kneeling and helpless within their spells, and only when the last of them falls is he free. Finally, he cries, his banishment ends. He fights with twin blades, spinning in a whirlwind of steel, but he is not alone in his body. From time to time a demon takes him over, mocking the trifling elf it has cast aside, wearing a fiend''s shape and whispering to his foes that we all have our demons.', 'creature_template 21215 (display 20514, BloodElfMale); fixed spawn 153139, map 548 only; smart_scripts 21806 (Greyheart Spellbinder: Green Beam out of combat, Banish in combat, on death checks the others; Leotheras wakes when none is left); boss_leotheras_the_blind.cpp (passive and kneeling until freed; SAY_AGGRO Finally, my banishment ends!; dual wield and Whirlwind; Metamorphosis with SAY_SWITCH_TO_DEMON Be gone, trifling elf. I am in control now!; Insidious Whisper with SAY_INNER_DEMONS We all have our demons....); warcraft.wiki.gg/wiki/Leotheras_the_Blind (blood elf demon hunter; kept banished by the Greyheart Spellbinders)'),
(360704, 2, 3607, 4, 0, 9, 'Fathom-Lord Karathress', 'Fathom-Lord Karathress is a naga lord of Serpentshrine Cavern, and he holds his chamber with three Fathom-Guards at his side: Sharkkis, a hunter with beasts at his call, Tidalvess, a shaman of totems and frost, and Caribdis, a caster of water and cyclones who mends her allies'' wounds. When intruders come he calls his guards to attention, for they have visitors, and he hurls bolts and searing novas at those who dare his hall. In a cage at the edge of his chamber sits a prisoner, a Broken called Seer Olum.', 'creature_template 21214 (display 20662, Naga_Male); fixed spawn 153154, map 548 only; DB spawns map 548: Fathom-Guard Caribdis 21964 (female model), Tidalvess 21965, Sharkkis 21966 beside him; Seer Olum 22820 (display 21101, BrokenMale) and gameobject 185474 Cage at the same spot; boss_fathomlord_karathress.cpp (Cataclysmic Bolt, Sear Nova; Sharkkis summons a Fathom Lurker and Sporebat, Tidalvess drops totems and Frost Shock, Caribdis summons a cyclone, Water Bolt Volley and Healing Wave); creature_text 21214 group 0 (Guards, attention! We have visitors....); instance_serpent_shrine.cpp (Olum has no gossip or quests until freed)'),
(360705, 2, 3607, 5, 0, 9, 'Morogrim Tidewalker', 'Morogrim Tidewalker is a giant of the sea who rules a shore of Serpentshrine Cavern, where the Tidewalker murlocs who bear his name crowd about the water: warriors, shamans, harpooners, hydromancers and depth-seers. He greets intruders with a curse, flood of the deep take you, and fights with the sea itself, hurling tidal waves, sealing foes in watery graves and shaking the ground with earthquakes. When the earth shakes the murlocs come running from the shallows, and he calls on his subjects to destroy his foes.', 'creature_template 21213 (type 5, display 20739 SeaGiant); fixed spawn 153169, map 548 only; DB spawns map 548: Tidewalker Warrior 21225, Shaman 21226, Harpooner 21227, Hydromancer 21228, Depth-Seer 21224 (murloc models); creature_text 21213 groups 0 (Flood of the deep, take you!), 1 (By the tides!; Destroy them, my subjects!), 6 (The violent earthquake has alerted nearby Murlocs!); boss_morogrim_tidewalker.cpp (Tidal Wave, Watery Grave, Earthquake followed by murloc summons with SAY_SUMMON)'),
(360706, 2, 3607, 6, 0, 9, 'Lady Vashj', 'Lady Vashj is the matron of the Coilfang naga and the mistress of Serpentshrine Cavern. Long ago she was one of the Highborne of ancient Kalimdor, a handmaiden to Queen Azshara, and she rose from the sea with her naga when Illidan Stormrage called on them; she has served him ever since, and followed him to Outland. Throughout Coilfang her naga cry that Illidan reigns. To any who reach her she declares her purpose: water is life, a rare commodity in Outland that her people alone shall control, and the time has come at last for the Highborne to retake their rightful place in the world.', 'creature_template 21212 (subname Coilfang Matron, display 20748); fixed spawn 153195, map 548 only; creature_text 21212 group 0 (Water... is life. It has become a rare commodity here in Outland; a commodity that we alone shall control. We are the Highborne, and the time has come at last for us to retake our rightful place in the world!, said once when a player first comes into sight) and group 1 (Victory to Lord Illidan!); creature_text 17726, 17800 and others (Illidan reigns!); Warcraft III: The Frozen Throne (2003) and The Well of Eternity (2004): Vashj a Highborne handmaiden of Azshara, summoned with her naga by Illidan, his servant in Outland; warcraft.wiki.gg/wiki/Lady_Vashj');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(360701, 1, 0, 255, 'Hydross fell in his chamber, and his last words depended on what he was when he died. Pure, he sighed that he was released. Poisoned, he turned on his killers with an accusation: they were the disease, not he. Either way, the Duke of Currents was no more.', 'creature_text 21216 groups 3 (I am... released.) and 6 (You... are the disease... not I...); boss_hydross_the_unstable.cpp JustDied (corrupt or clean death line by his form)'),
(360702, 1, 0, 255, 'The Lurker Below died in its pool. With it went the danger of the cavern''s water: after its fall the frenzies no longer swarmed about those who swam, and the water of Serpentshrine could be crossed in peace.', 'instance_serpent_shrine.cpp (spell_serpentshrine_cavern_coilfang_water: no frenzies or scalding water once DATA_THE_LURKER_BELOW is DONE)'),
(360703, 1, 0, 255, 'Near the end the elf took back his body, but the struggle broke him: no, he cried, he was the master, and he could not contain him. His demon tore free as a shadow of its own, rejoicing that it was liberated at last, and the two fought on side by side until Leotheras fell, and his shadow vanished with him.', 'creature_text 21215 group 5 (No... no! What have you done? I am the master! ... Can''t... contain him.) and 21875 group 1 (At last I am liberated. It has been too long since I have tasted true freedom!); boss_leotheras_the_blind.cpp (at 15 percent health he kneels, speaks SAY_FINAL_FORM and summons the Shadow of Leotheras 21875, a summon despawned with him)'),
(360704, 1, 0, 255, 'As each of the Fathom-Guards fell, its power passed to its lord, but Karathress could not hold his hall. When the fathom-lord died, the cage at the edge of his chamber swung open, and its prisoner, Seer Olum, walked free.', 'boss_fathomlord_karathress.cpp (each Fathom-Guard casts Power of Sharkkis, Tidalvess or Caribdis on him at death; JustDied opens the Cage 185474 and walks Seer Olum 22820 out, giving him gossip and quests)'),
(360705, 1, 0, 255, 'As he weakened the Tidewalker sent globules of water to hunt his foes instead of graves, but he fell all the same on the shore he ruled. His last words meant nothing to those who heard them: great currents of Ageon.', 'creature_text 21213 group 4 (Great currents of... Ageon...); boss_morogrim_tidewalker.cpp (below 25 percent health Watery Globules replace Watery Grave; JustDied: SAY_DEATH)'),
(360706, 1, 0, 255, 'Vashj fought with bow and lightning, then drew back to the heart of her platform behind a barrier fed by four shield generators, calling elementals, elite naga and striders against her foes. When the barrier fell she came on again under clouds of toxic sporebats. At the last she died with an apology to her master: Lord Illidan, I am sorry.', 'creature_text 21212 group 7 (Lord Illidan, I... I am... sorry.); boss_lady_vashj.cpp (Shoot, Multi-Shot, Shock Blast, Static Charge, Entangle; at 70 percent she returns home, Magic Barrier from the four Shield Generators 185051-185054, summons Enchanted and Tainted Elementals, Coilfang Elites and Striders; when the barrier is gone she fights on with Toxic Sporebats; JustDied: SAY_DEATH)');
